420	// `searchJiraIssuesUsingJql` page, or a Linear `list_milestones` answer),
421	// prints the decision one field per line, and writes exactly one
422	// `milestone-decision` receipt under <projectRoot>. Everything is decided
423	// first and written last: every refusal exits 1 with an NFR-10 message on
424	// stderr, nothing on stdout and nothing on disk.
425	
426	/** A refusal the front door exits 1 on; its message is NFR-10 three-line. */
427	class FrontDoorRefusal extends Error {
428	  constructor(verdict: string, remedy: string, context: string) {
429	    // Each part is flattened BEFORE the lines are joined: a listing's keys and
430	    // issue types are tracker-controlled text, and a newline in one must never
431	    // start a line of its own (a forged `Remedy:` — or a `dpt-receipt:`).
432	    super(nfr10Message(oneLine(verdict), oneLine(remedy), oneLine(context)));
433	    this.name = "FrontDoorRefusal";
434	  }
435	}
436	
437	/**
438	 * The most rows one Linear `list_milestones` answer returns — defined once, in
439	 * `tracker_answer.ts`, and re-exported here for this module's importers. A
440	 * full window may be the window rather than the project.
441	 */
442	export { LINEAR_MILESTONE_WINDOW } from "./tracker_answer";
443	
444	const FRONT_DOOR_USAGE =
445	  "resolve_milestone_identity.ts <projectRoot> <jira|linear> <project> <listingFile> --title <title> | --join-key <key> [--sibling <path>]";
446	
447	interface FrontDoorArgs {
448	  projectRoot: string;
449	  mode: "jira" | "linear";
450	  project: string;
451	  listingFile: string;
452	  title?: string;
453	  joinKey?: string;
454	  sibling?: string;
455	}
456	
457	function parseFrontDoorArgs(argv: readonly string[]): FrontDoorArgs {
458	  const context = `argc=${argv.length}, usage=${FRONT_DOOR_USAGE}`;
459	  const hasSibling = argv.length === 8;
460	  if (argv.length !== 6 && !(hasSibling && argv[6] === "--sibling")) {
461	    throw new FrontDoorRefusal(
462	      `Refusing: incomplete or extra arguments — the decision needs a project root, a mode, a project, a listing file and exactly one of --title or --join-key.`,
463	      `run ${FRONT_DOOR_USAGE}`,
464	      context,
465	    );
466	  }
467	  const [projectRoot, mode, project, listingFile, flag, value] = argv as [string, string, string, string, string, string];
468	  if (mode !== "jira" && mode !== "linear") {
469	    throw new FrontDoorRefusal(
470	      `Refusing: unknown mode "${mode}" — only jira and linear list milestone containers to decide against.`,
471	      `pass mode jira or linear.`,
472	      `mode=${mode}, ${context}`,
473	    );
474	  }
475	  const sibling = hasSibling ? argv[7]! : undefined;
476	  if ((flag !== "--title" && flag !== "--join-key") || value === "" || projectRoot === "" || project === "" || listingFile === "" || sibling === "") {
477	    throw new FrontDoorRefusal(
478	      `Refusing: incomplete arguments — expected a non-empty --title or --join-key after the listing file (got ${flag}).`,
479	      `run ${FRONT_DOOR_USAGE}`,
480	      context,
481	    );
482	  }
483	  return {
484	    projectRoot: resolve(projectRoot),
485	    mode,
486	    project,
487	    listingFile,
488	    ...(flag === "--title" ? { title: value } : { joinKey: value }),
489	    ...(sibling !== undefined ? { sibling } : {}),
490	  };
491	}
