493	/** A tracker listing file, parsed and proven complete (STE-608; reused by STE-611's attach front door). */
494	export interface ReadListing {
495	  sha256: string;
496	  rowKeys: string[];
497	  /**
498	   * False when the listing may not hold every container: a Linear milestones
499	   * answer of a full LINEAR_MILESTONE_WINDOW rows. A Jira listing that does
500	   * not prove it is the last page is refused instead, so it is always true.
501	   */
502	  complete: boolean;
503	  jiraRows?: (JiraDecisionRow & { statusName?: string })[];
504	  linearRows?: LinearDecisionRow[];
505	}
506	
507	function isObject(v: unknown): v is Record<string, unknown> {
508	  return v !== null && typeof v === "object" && !Array.isArray(v);
509	}
510	
511	/**
512	 * Read, parse and shape-check one saved tracker listing: a raw Jira Epic search
513	 * page that PROVES it is the last one, or a Linear `{ milestones: [...] }`
514	 * answer. Every failure throws an NFR-10 refusal whose parts are flattened.
515	 * Exported so the attach front door (STE-611) parses the same format through
516	 * the same code rather than a second parser.
517	 */
518	export function readListingFile(args: Pick<FrontDoorArgs, "mode" | "project" | "listingFile">): ReadListing {
519	  const context = `mode=${args.mode}, project=${args.project}, listing=${args.listingFile}`;
520	  let bytes: Buffer;
521	  try {
522	    bytes = readFileSync(args.listingFile);
523	  } catch (e) {
524	    throw new FrontDoorRefusal(
525	      `Refusing: the listing file ${args.listingFile} cannot be read (${(e as NodeJS.ErrnoException).code ?? (e as Error).message}).`,
526	      `save the tracker's listing answer to a readable file and pass its path.`,
527	      context,
528	    );
529	  }
530	  let parsed: unknown;
531	  try {
532	    parsed = JSON.parse(bytes.toString("utf-8"));
533	  } catch (e) {
534	    throw new FrontDoorRefusal(
535	      `Refusing: the listing file ${args.listingFile} is not JSON (${(e as Error).message}).`,
536	      `save the tracker's raw JSON answer, unedited, and pass its path.`,
537	      context,
538	    );
539	  }
540	  const sha256 = createHash("sha256").update(bytes).digest("hex");
541	  const shape = (what: string): FrontDoorRefusal =>
542	    new FrontDoorRefusal(
543	      `Refusing: the listing file ${args.listingFile} is not a recognised ${args.mode} listing — ${what}.`,
544	      args.mode === "jira"
545	        ? `save the raw searchJiraIssuesUsingJql answer ({ issues: [...] }) for project ${args.project}'s Epics.`
546	        : `save the raw list_milestones answer ({ milestones: [...] }) for project ${args.project}.`,
547	      context,
548	    );
549	
550	  // Both listings are read by the one reader of tracker answers
551	  // (`tracker_answer.ts`): an answer in no observed shape is not a listing.
552	  const read = readTrackerPage(args.mode, parsed, "milestones");
553	  if (!read.ok) throw shape(read.reason);
554	
555	  if (args.mode === "linear") {
556	    const rows: LinearDecisionRow[] = [];
557	    for (const m of read.page.items) {
558	      if (typeof m.id !== "string" || m.id === "" || typeof m.name !== "string") {
559	        throw shape("a milestone row carries no string `id` and `name`");
560	      }
561	      rows.push({ id: m.id, name: m.name });
562	    }
563	    return { sha256, rowKeys: rows.map((r) => r.id!), linearRows: rows, complete: read.page.last };
564	  }
565	
566	  // A page that does not PROVE it is the last one has not proven the container
567	  // absent — the rule create_idempotency_probe applies to the same Jira search
568	  // answer, in either of its shapes.
569	  if (!read.page.last) {
570	    throw new FrontDoorRefusal(
571	      `Refusing: the listing file ${args.listingFile} is not the last page of the Epic search (it hands the cursor ${oneLine(read.page.next ?? "")} for a page after it) — a later page may hold the container this decision would miss.`,
572	      `page the search to the end and save one listing holding every Epic, then decide again.`,
573	      context,
574	    );
575	  }
576	  const rows: (JiraDecisionRow & { statusName?: string })[] = [];
577	  for (const issue of read.page.items) {
578	    if (typeof issue.key !== "string" || issue.key === "" || !isObject(issue.fields)) {
579	      throw shape("an issue row carries no `key` and `fields`");
580	    }
581	    const key = issue.key;
582	    const f = issue.fields;
583	    if (typeof f.summary !== "string") throw shape(`issue ${key} carries no string \`summary\``);
584	    const projectKey = isObject(f.project) && typeof f.project.key === "string" ? f.project.key : undefined;
585	    if (projectKey !== args.project || !key.startsWith(`${args.project}-`)) {
586	      throw new FrontDoorRefusal(
587	        `Refusing: issue ${key} is keyed outside project ${args.project} (project ${projectKey ?? "absent"}) — the file is not that project's Epic listing.`,
588	        `enumerate project ${args.project}'s Epics only, save that answer, and decide again.`,
589	        `${context}, row=${key}`,
590	      );
591	    }
592	    const typeName = isObject(f.issuetype) && typeof f.issuetype.name === "string" ? f.issuetype.name : undefined;
593	    if (typeName !== "Epic") {
594	      throw new FrontDoorRefusal(
595	        `Refusing: issue ${key} is ${typeName === undefined ? "listed with no issue type" : `a ${typeName}, not an Epic`} — the file is not project ${args.project}'s Epic listing.`,
596	        `enumerate project ${args.project}'s Epics with the issuetype field, save that answer, and decide again.`,
597	        `${context}, row=${key}, issuetype=${typeName ?? "absent"}`,
598	      );
599	    }
600	    const status = isObject(f.status) ? f.status : undefined;
601	    const category = status && isObject(status.statusCategory) && typeof status.statusCategory.key === "string"
602	      ? status.statusCategory.key
603	      : undefined;
604	    const labels = Array.isArray(f.labels) ? (f.labels as unknown[]).filter((l): l is string => typeof l === "string") : undefined;
605	    rows.push({
606	      key,
607	      name: f.summary,
608	      ...(category !== undefined ? { statusCategory: category } : {}),
609	      ...(status && typeof status.name === "string" ? { statusName: status.name } : {}),
610	      ...(labels !== undefined ? { labels } : {}),
611	    });
612	  }
613	  return { sha256, rowKeys: rows.map((r) => r.key), jiraRows: rows, complete: true };
614	}
615	
616	/**
617	 * STE-610 AC-STE-610.4 — the sibling a shared join names, verified by the span
618	 * checks as a dry run: nothing is written into either plan, and this side's
619	 * plan does not exist yet, so none is graded. The milestone is the joined
620	 * key's id — the token both plans are named after.
621	 */
622	async function verifyJoinSibling(
623	  args: FrontDoorArgs,
624	  milestoneId: string,
625	): Promise<{ tag: string; path: string }> {
626	  // A refusal is the span reader's own NFR-10 text; the front door's catch
627	  // prints it verbatim, line by line through `printable`.
628	  const v = await verifySpan({
629	    invokingRepo: args.projectRoot,
630	    planFile: null,
631	    milestone: milestoneId,
632	    siblingPath: args.sibling!,
633	    dryRun: true,
634	  });
635	  return { tag: v.siblingTag, path: v.siblingRoot };
636	}
637	
638	/** Decide, then write the one receipt, then return the lines to print. */
639	async function runDecisionFrontDoor(argv: readonly string[]): Promise<string[]> {
640	  const args = parseFrontDoorArgs(argv);
641	  const listing = readListingFile(args);
642	
643	  // The shared flag and the floor: each reader's own refusal propagates, so an
644	  // unreadable or refused declaration is never read as unshared.
645	  const binding = readWorkspaceBinding(join(args.projectRoot, "CLAUDE.md"), args.mode);
646	  const floor = checkVersionFloor(binding, runningDptVersion());
647	  if (!floor.ok) throw new Error(floor.message);
648	
649	  const pick = args.joinKey !== undefined ? { joinKey: args.joinKey } : { title: args.title };
650	  const decision = decideFromListing(
651	    args.mode,
652	    args.project,
653	    args.mode === "jira" ? listing.jiraRows! : listing.linearRows!,
654	    pick,
655	  );
656	
657	  const rowCount = listing.rowKeys.length;
658	  // LIN-7 (M_685ff6 review): Linear's list_milestones answers at most
659	  // LINEAR_MILESTONE_WINDOW rows and proves nothing about the rest, so a
660	  // listing of exactly that many may be the window, not the project.
661	  const possiblyCapped = !listing.complete;
662	  const listingLine =
663	    args.mode === "jira"
664	      ? `${rowCount} rows, ${listing.jiraRows!.filter((r) => r.statusCategory === "done").length} closed excluded`
665	      : `${rowCount} rows, closed rule not applicable (Linear milestones carry no status)${
666	          possiblyCapped
667	            ? `, possibly capped (list_milestones returns at most ${LINEAR_MILESTONE_WINDOW} milestones, so a same-title milestone past the window is unseen)`
668	            : ""
669	        }`;
670	
671	  const milestoneId = decision.act === "join" ? joinedMilestoneId(args.mode, decision.key) : "";
672	
673	  // STE-610 AC-STE-610.4 — `--sibling` names a shared join's sibling, and
674	  // nothing else: an unshared repository and a create both refuse it.
675	  const ctx = `mode=${args.mode}, project=${args.project}, act=${decision.act}, shared=${binding.shared}`;
676	  if (args.sibling !== undefined && !binding.shared) {
677	    throw new FrontDoorRefusal(
678	      `Refusing: --sibling names the sibling of a join in a shared repository, and ${args.projectRoot} declares no repo_tag — its binding is not shared.`,
679	      `drop --sibling and decide again; an unshared repository joins without one.`,
680	      ctx,
681	    );
682	  }
683	  if (args.sibling !== undefined && decision.act !== "join") {
684	    throw new FrontDoorRefusal(
685	      `Refusing: --sibling names the sibling of a join, and the listing decided a create of "${args.title ?? ""}" — there is no joined milestone for the sibling to plan.`,
686	      `drop --sibling to create, or pass --join-key <key> naming the container the sibling planned.`,
687	      ctx,
688	    );
689	  }
690	  if (decision.act === "join" && binding.shared && args.sibling === undefined) {
691	    throw new FrontDoorRefusal(
692	      `Refusing: the listing decided a join of ${decision.key} (${milestoneId}) in a shared repository, and no --sibling names the repository that planned it.`,
693	      `pass --sibling <path> naming the sibling repository whose plan holds ${milestoneId}, or pass a distinct --title to create a new container instead.`,
694	      `${ctx}, key=${decision.key}`,
695	    );
696	  }
697	  const sibling = args.sibling !== undefined ? await verifyJoinSibling(args, milestoneId) : undefined;
698	
699	  const sentence = milestoneGateSentence({
700	    mode: args.mode,
701	    project: args.project,
702	    title: args.title,
703	    decision,
704	    rows: listing.jiraRows ?? [],
705	    shared: binding.shared,
706	    ...(sibling !== undefined ? { sibling } : {}),
707	  });
708	  // A create decided from a possibly capped listing has no safe default: the
709	  // operator answers it, after searching the tracker for the title by hand.
710	  const cappedCreate = possiblyCapped && decision.act === "create";
711	  const gate = cappedCreate
712	    ? `${sentence.gate} The listing holds exactly ${LINEAR_MILESTONE_WINDOW} milestones and may be capped: search project ${args.project} for "${args.title ?? ""}" past the first ${LINEAR_MILESTONE_WINDOW} before approving.`
713	    : sentence.gate;
714	  const forbidden = sentence.forbidden || cappedCreate;
715	
716	  const act = decision.act;
717	  const via = decision.act === "join" ? decision.via : "";
718	  const key = decision.act === "join" ? decision.key : "";
719	  const lines = [
720	    `act=${act}`,
721	    `via=${via}`,
722	    `key=${key}`,
723	    `milestoneId=${milestoneId}`,
724	    `listing=${listingLine}`,
725	    `gate=${gate}`,
726	    `default=${forbidden ? "forbidden" : "allowed"}`,
727	  ];
728	  // STE-608 AC-STE-608.9 — a Jira join prints the computed label value: the
729	  // Epic's labels as listed plus the milestone label, or `unchanged`.
730	  const observedLabels = decision.act === "join" && args.mode === "jira" ? decision.labels : undefined;
731	  if (observedLabels !== undefined) {
732	    const merged = mergeMilestoneLabel(observedLabels, milestoneId);
733	    lines.push(`labels=${merged === null ? "unchanged" : JSON.stringify(merged)}`);
734	  }
735	  const printed = lines.map(printable);
736	
737	  // Decided — write last.
738	  const path = writeReceipt(args.projectRoot, {
739	    kind: "milestone-decision",
740	    adapter: args.mode,
741	    container: args.project,
742	    subject: args.joinKey ?? args.title ?? "",
743	    decision: act,
744	    evidence: {
745	      act,
746	      via,
747	      key,
748	      milestoneId,
749	      ...(args.joinKey !== undefined ? { joinKey: args.joinKey } : { title: args.title }),
750	      // The joined container's listed name: the hook reads it to let a later
751	      // join by key govern a create of that title (M_685ff6 review).
752	      ...(decision.act === "join" ? { name: decision.name } : {}),
753	      ...(decision.act === "create" && decision.excluded ? { excluded: decision.excluded } : {}),
754	      ...(observedLabels !== undefined ? { labels: observedLabels } : {}),
755	      shared: binding.shared,
756	      ...(possiblyCapped ? { possiblyCapped: true } : {}),
757	      ...(sibling !== undefined ? { sibling: { tag: sibling.tag, path: sibling.path, given: args.sibling } } : {}),
758	      default: forbidden ? "forbidden" : "allowed",
759	      listing: { file: resolve(args.listingFile), sha256: listing.sha256, rowKeys: listing.rowKeys },
760	    },
761	  });
762	  return [...printed, announceReceipt(path)];
763	}
764	
765	if (import.meta.main) {
766	  try {
767	    const lines = await runDecisionFrontDoor(process.argv.slice(2));
768	    process.stdout.write(`${lines.join("\n")}\n`);
769	    process.exit(0);
770	  } catch (e) {
771	    const message = (e as Error).message ?? String(e);
772	    const text = /^Remedy:/m.test(message) && /^Context:/m.test(message)
773	      ? message
774	      : nfr10Message(
775	          `Refusing: ${message}`,
776	          `fix the input named above and run the decision again.`,
777	          `helper=resolve_milestone_identity, phase=milestone-decision-front-door`,
778	        );
779	    process.stderr.write(`${text.split("\n").map(printable).join("\n")}\n`);

// repoint_tracker_binding — STE-612.
//
// /setup's repoint flag (§ 0c) re-points a repository's tracker binding
// at another project of the same tracker. `docs/setup-reference.md` § 0c lists
// the preconditions for that flip; this module decides rows 1 to 7 in code
// from the tracker listings the session saves to files and passes in, then
// reports row 8 after the write.
//
// Front doors:
//   bun run adapters/_shared/src/repoint_tracker_binding.ts <projectRoot> <mode> <newProject>
//     --projects <file> --containers <file> [--issue-types <file>] [--statuses <file>]
//     [--labels <file>] [--peer <path>]… [--team <team>]
//   bun run adapters/_shared/src/repoint_tracker_binding.ts <projectRoot> --verify
//
// A repoint prints one `<n> PASS|REFUSE|NOT-APPLICABLE <reason>` line per row,
// rows 1 to 7 in order, and exits 1 when any row refuses — having written
// nothing. When none refuses it re-points CLAUDE.md through
// `writeTrackerSubsection` (STE-603) alone, writes one `repoint` receipt
// (STE-602), prints row 8's `8 …` report lines (branches and worktrees still
// binding the old project, and the legacy bindings that keep it alive), and
// prints the receipt's `dpt-receipt:` line last.
// A row whose input is absent, unreadable or malformed REFUSES; it never
// passes on an input it could not read.
//
// `--verify` re-reads `specs/tracker-config.yaml` against the status snapshot
// of this session's latest `repoint` receipt and prints `verify PASS|FAIL`.
// It writes nothing.
//
// Not every run is a repoint. A sub-section whose `project:` is absent or the
// `<deferred>` placeholder is a RESUME; one already bound to `<newProject>` is
// a DECLARE (STE-603). Neither runs the rows: the command prints `resume` or
// `declare` and hands straight to the sub-section writer.

import { existsSync, readFileSync, realpathSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import {
  listingProvider,
  milestoneLabel,
  planFileHeadingToMilestoneName,
  resolveAttachTarget,
} from "./attach_project_milestone";
import { readActiveSpecsFromGit, type ActiveSpecsRead } from "./active_plan_ship_ready";
import { nfr10Message } from "./dpt_version";
import { parseFrontmatter } from "./frontmatter";
import { parseMilestoneToken } from "./milestone_token";
import { parsePlanHeading } from "./plan_heading";
import { readListingFile, type ReadListing } from "./resolve_milestone_identity";
import { readTaskTrackingSection } from "./resolver_config";
import { writeTrackerSubsection } from "./setup/tracker_binding_write";
import { parseWorktreePorcelain, runGit } from "./target_repo";
import {
  epicTokenOutside,
  epicTokenPrefix,
  activeJiraKeyOf,
  foreignJiraKeyProject,
  jiraKeyOf,
  mdFiles,
  runTaskTrackingWorkspaceBindingPresentProbe,
} from "./task_tracking_workspace_binding_present";
import { readTrackerConfig } from "./tracker_config";
import { announceReceipt, oneLine, printable, readSessionReceipts, writeReceipt } from "./tracker_receipts";
import {
  locateSubsection,
  readWorkspaceBinding,
  type WorkspaceAdapterKey,
  type WorkspaceBinding,
} from "./workspace_binding";
import { readCompleteList, readTrackerPage, type CompleteListTool } from "./tracker_answer";

export type RowVerdict = "PASS" | "REFUSE" | "NOT-APPLICABLE";

export interface RowResult {
  row: number;
  verdict: RowVerdict;
  reason: string;
  /** Row 4 only: the tracker config's statuses, the snapshot the `repoint` receipt records. */
  statusSnapshot?: string[];
  /**
   * The inputs whose completeness this row relied on as ASSERTED by the
   * session (an `isLast: true` the session wrote), not proven by the tracker —
   * the receipt's `assertedCompleteness`. Absent when every input was proven.
   */
  asserted?: AssertedInput[];
}

/**
 * An input whose COMPLETENESS the session asserts rather than the tracker proves.
 *
 * The older wording here said "an input no tracker tool lists", which was true
 * when it was written and is not true now: Jira statuses ARE listable, through
 * the adapter's declared `list_project_statuses` capability. That correction
 * landed in `docs/setup-reference.md` and in `readStatuses` below, and this
 * comment one file away kept describing the world before it.
 *
 * Three states, deliberately distinguished, because collapsing them is how a
 * weaker claim gets laundered into a stronger one's wording:
 *   - `labels`              — genuinely unlistable; no Atlassian tool lists them.
 *   - `statuses`            — a full listing; plausibly complete, unprovably so.
 *   - `statuses:transitions`— derived from ONE issue's available transitions, so
 *     it is the set reachable from that issue's current state: PARTIAL BY
 *     CONSTRUCTION, not merely unproven. Row 4 refuses when the config lacks a
 *     status the listing names, so a shorter list is strictly EASIER to pass —
 *     which makes recording this distinctly a correctness matter and not
 *     bookkeeping.
 */
export type AssertedInput = "statuses" | "labels" | "statuses:transitions";

